<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\File;
use Inertia\Inertia;
use Inertia\Response;

/**
 * Public essays section for dvaughnhouse.org.
 *
 * Source of truth is the markdown in resources/essays/*.md; the .html files
 * beside them are generated by resources/essays/build.sh and served as-is.
 */
class EssayController extends Controller
{
    /**
     * Manifest of published essays. Slug => metadata.
     * Only slugs listed here are routable (no path traversal).
     */
    private const DOCUMENTS = [
        'power-wisdom-gap' => [
            'file' => 'power-wisdom-gap.html',
            'id' => 'ESSAY-001',
            'title' => 'The Power-Wisdom Gap and the Imperative for Independent Infrastructure',
            'status' => 'Expanded Edition v2 · October 2026',
            'meta' => '~9,500 words · 123 verified sources · 9 sections',
            'description' => 'The flagship essay and founder\'s thesis: our technological capabilities are outpacing our wisdom and governance, and the answer is independent infrastructure built under Human Primacy. Written as the standard Glenride\'s scholars are held to — every claim wired to evidence, limits stated plainly.',
        ],
    ];

    /**
     * Slugs of the published essays (used for counts on the home page).
     *
     * @return array<int, string>
     */
    public static function publishedSlugs(): array
    {
        return array_keys(self::DOCUMENTS);
    }

    /**
     * Display the essays index.
     */
    public function index(Request $request): Response
    {
        $documents = [];
        foreach (self::DOCUMENTS as $slug => $meta) {
            $documents[] = array_merge(['slug' => $slug], $meta);
            unset($documents[count($documents) - 1]['file']);
        }

        return Inertia::render('Essays/Index', [
            'documents' => $documents,
        ]);
    }

    /**
     * Display a single essay.
     */
    public function show(Request $request, string $slug): Response
    {
        if (! array_key_exists($slug, self::DOCUMENTS)) {
            abort(404, 'Essay not found.');
        }

        $meta = self::DOCUMENTS[$slug];
        $path = resource_path('essays/' . $meta['file']);

        if (! File::exists($path)) {
            abort(404, 'Essay not found.');
        }

        $document = array_merge(['slug' => $slug], $meta);
        unset($document['file']);
        $document['html'] = File::get($path);

        return Inertia::render('Essays/Show', [
            'document' => $document,
        ]);
    }
}
